/* Studora renderer: local UI only. Network and credentials stay in the main process. */
(()=>{
'use strict';
const api=window.studora,$=s=>document.querySelector(s),esc=x=>String(x??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c])),id=()=>crypto.randomUUID();
let updateState={status:'idle',currentVersion:'0.1.1'},S,connected=false,connectionPersistent=true,view='home',subjectId=null,tab='Tutor',chatId=null,lessonId=null,noteId=null,example='',busy=false,error='',draft='',activeSources=[],contextSource=null,contextPage=1,saveTimer,toastTimer,importing=false,board=null;
const icon=n=>`<i data-lucide="${n}" aria-hidden="true"></i>`;
const btn=(label,action,cls='secondary',attrs='')=>`<button type="button" class="${cls}" data-action="${action}" ${attrs}>${label}</button>`;
const subject=()=>S.subjects.find(x=>x.id===subjectId),lesson=()=>S.lessons.find(x=>x.id===lessonId),chat=()=>S.chats.find(x=>x.id===chatId),subjectsSources=()=>S.sources.filter(x=>x.subjectId===subjectId&&!x.retired);
const today=()=>new Intl.DateTimeFormat('en-CA',{timeZone:'Asia/Riyadh',year:'numeric',month:'2-digit',day:'2-digit'}).format(new Date());
function days(date){return Math.ceil((new Date(date+'T00:00:00+03:00')-new Date(today()+'T00:00:00+03:00'))/86400000)}
function toast(text){$('#toast').textContent=text;$('#toast').classList.add('show');clearTimeout(toastTimer);toastTimer=setTimeout(()=>$('#toast').classList.remove('show'),4200)}
function sound(done=false){if(!S.settings.sound)return;try{const c=new AudioContext(),o=c.createOscillator(),g=c.createGain();o.type='sine';o.frequency.setValueAtTime(done?660:460,c.currentTime);if(done)o.frequency.setValueAtTime(880,c.currentTime+.09);g.gain.setValueAtTime(.025,c.currentTime);g.gain.exponentialRampToValueAtTime(.0001,c.currentTime+.16);o.connect(g);g.connect(c.destination);o.start();o.stop(c.currentTime+.17);o.onended=()=>c.close()}catch{}}
function persist(){S.ui={subject:subjectId,tab,chat:chatId,lesson:lessonId,view};clearTimeout(saveTimer);saveTimer=setTimeout(()=>api.save(S).catch(e=>toast('Could not save: '+e.message)),250)}
async function flush(){clearTimeout(saveTimer);S.ui={subject:subjectId,tab,chat:chatId,lesson:lessonId,view};await api.save(S)}
function icons(){lucide.createIcons({attrs:{width:16,height:16}})}
function applyTheme(){const theme=S.settings.theme==='system'?(matchMedia('(prefers-color-scheme: dark)').matches?'dark':'light'):S.settings.theme;document.body.dataset.theme=theme;document.documentElement.style.setProperty('--sidebar',S.settings.sidebarWidth+'px');$('#mute').innerHTML=icon(S.settings.sound?'volume-2':'volume-x');$('#mute').title=S.settings.sound?'Mute sounds':'Enable sounds';$('#mute').setAttribute('aria-label',$('#mute').title)}
function md(text){const citations=[];const replaced=String(text).replace(/\[\[([a-f0-9-]{36}):(\d+)\]\]/g,(_,src,page)=>{const source=S.sources.find(x=>x.id===src);if(!source||!source.pages.some(x=>x.page===Number(page)))return '';const token='STUDORACITE'+citations.length+'END';citations.push({token,src,page,name:source.name});return token});let html=DOMPurify.sanitize(marked.parse(replaced),{FORBID_TAGS:['img','iframe','object','style','form','input','button'],FORBID_ATTR:['style']});for(const c of citations)html=html.replaceAll(c.token,`<button class="citation" data-action="citation" data-source="${c.src}" data-page="${c.page}">${esc(c.name)} · ${c.page}</button>`);return html}
function mathRender(host){try{renderMathInElement(host,{delimiters:[{left:'$$',right:'$$',display:true},{left:'$',right:'$',display:false},{left:'\\(',right:'\\)',display:false},{left:'\\[',right:'\\]',display:true}],throwOnError:false,trust:false})}catch{}}
function openSubject(sid){draft=$('#prompt')?.value||draft;subjectId=sid;view='subject';contextSource=null;$('#context').hidden=true;const prev=S.chats.filter(x=>x.subjectId===sid&&!x.archived).sort((a,b)=>b.updatedAt.localeCompare(a.updatedAt))[0];chatId=prev?.id||null;lessonId=prev?.lessonId||null;activeSources=prev?.sourceIds||subjectsSources().map(x=>x.id);tab='Tutor';draft='';error='';render();persist();sound()}
function renderRail(){const rail=$('#subject-rail');rail.innerHTML=S.subjects.map(s=>`<button data-action="subject" data-id="${s.id}" class="${view==='subject'&&subjectId===s.id?'selected':''}" title="${esc(s.name)}" aria-label="${esc(s.name)}" style="--subject:${esc(s.color)}">${icon(s.icon||'book-open')}<span class="subject-dot"></span></button>`).join('');$('.rail-home').classList.toggle('selected',view==='home')}
function renderSidebar(){const side=$('#sidebar');if(view==='settings'){side.innerHTML=`<div class="sidebar-head"><h2>Settings</h2></div><p class="list-placeholder">Make Studora feel like your workspace.</p><div class="nav">${btn('Appearance','settings-anchor','item','data-anchor="appearance"')}${btn('AI connection','settings-anchor','item','data-anchor="connection"')}${btn('Learning preferences','settings-anchor','item','data-anchor="learning"')}${btn('Subjects & organization','settings-anchor','item','data-anchor="organization"')}${btn('Your data','settings-anchor','item','data-anchor="data"')}${btn('Updates','settings-anchor','item','data-anchor="updates-settings"')}</div><div class="sidebar-footer"><small>Studora ${esc(updateState.currentVersion)}<br>Personal desktop workspace</small></div>`;return}
if(view==='home'){side.innerHTML=`<div class="sidebar-head"><h2>Your workspace</h2></div>${btn(icon('search')+'Search everything','search','search-button')}<div class="sidebar-label eyebrow">STUDY</div>${btn(icon('house')+'Overview','home','item selected')}${btn(icon('calendar-days')+'Upcoming exams','exam','item')}<div class="sidebar-label eyebrow">SUBJECTS</div>${S.subjects.map(s=>btn(`<span style="width:6px;height:6px;border-radius:50%;background:${esc(s.color)}"></span>${esc(s.name)}`,'subject','item',`data-id="${s.id}"`)).join('')}<div class="sidebar-footer"><small>One lesson at a time.<br>Everything saved on this computer.</small></div>`;return}
const s=subject();const lessons=S.lessons.filter(x=>x.subjectId===subjectId);const chats=S.chats.filter(x=>x.subjectId===subjectId&&!x.archived);const groups=[...new Set(lessons.map(x=>x.chapter))];side.innerHTML=`<div class="sidebar-head"><h2>${esc(s?.name)}</h2>${btn(icon('ellipsis'),'subject-menu','icon-button',`aria-label="Subject options"`)}</div>${btn(icon('plus')+'New conversation','new-chat','new-chat')}${btn(icon('search')+'Search chats & notes','search','search-button')}<div class="sidebar-label eyebrow">PINNED</div>${chats.filter(x=>x.pinned).map(chatRow).join('')||'<div class="list-placeholder">Pin a chat to keep it here.</div>'}<div class="sidebar-label eyebrow">CHAPTERS & LESSONS ${btn(icon('plus'),'add-lesson','icon-button','aria-label="Add lesson"')}</div>${groups.map(group=>`<div class="chapter-label">${esc(group)}</div>${lessons.filter(x=>x.chapter===group).map(l=>`<div class="lesson-row">${btn(icon('book-open')+esc(l.number)+' '+esc(l.title),'lesson','item '+(lessonId===l.id?'selected':''),`data-id="${l.id}"`)}${btn(icon('ellipsis'),'edit-lesson','icon-button',`data-id="${l.id}" aria-label="Edit ${esc(l.number)}"`)}</div>${chats.filter(c=>c.lessonId===l.id&&!c.pinned&&!c.folder).map(chatRow).join('')}`).join('')}`).join('')||'<div class="list-placeholder">Add lessons from your book.<br>Numbering such as 2.1 stays intact.</div>'}<div class="sidebar-label eyebrow">OTHER CHATS</div>${chats.filter(x=>!x.lessonId&&!x.pinned&&!x.folder).map(chatRow).join('')||''}${[...new Set(chats.filter(c=>c.folder&&!c.pinned).map(c=>c.folder))].map(folder=>`<div class="sidebar-label eyebrow">${esc(folder)}</div>${chats.filter(c=>c.folder===folder&&!c.pinned).map(chatRow).join('')}`).join('')}<div class="sidebar-footer">${btn(icon('archive')+'Archived chats','archives','item')}${btn(icon('files')+'Study materials','sources-tab','item')}<small>${subjectsSources().length} sources · ${lessons.length} lessons</small></div>`}
function chatRow(c){return `<div class="chat-row">${btn(icon(c.pinned?'pin':'message-square')+esc(c.title),'chat','item '+(c.id===chatId?'selected':''),`data-id="${c.id}"`)}</div>`}
function header(title,crumb='',actions=''){return `<header class="page-header"><div><div class="breadcrumb">${esc(crumb)}</div><h1>${esc(title)}</h1></div><div class="header-actions">${actions}</div></header>`}
function render(){applyTheme();renderUpdateButton();renderRail();renderSidebar();const main=$('#main');if(view==='home')renderHome(main);else if(view==='settings')renderSettings(main);else renderSubject(main);icons()}
function renderHome(main){const exams=S.exams.filter(x=>days(x.date)>=0).sort((a,b)=>a.date.localeCompare(b.date));const recent=S.chats.filter(x=>!x.archived&&x.messages.length).sort((a,b)=>b.updatedAt.localeCompare(a.updatedAt))[0];main.innerHTML=header('Overview','Your workspace',btn(icon('plus')+'Add exam','exam','secondary'))+`<div class="content"><div class="home-content"><div class="eyebrow">MAKE ROOM TO UNDERSTAND</div><h2 class="hero-heading">A little clearer, every day.</h2><p class="lead">Learn from your materials, ask as many questions as you need, and keep everything together.</p>${!connected?`<div class="welcome-strip"><p><strong>Your tutor is waiting.</strong><br>Connect your separate OpenAI API account. Your files and notes work without it.</p>${btn('Connect AI '+icon('arrow-up-right'),'settings','secondary')}</div>`:''}<div class="section-head"><h2>Where to focus</h2><span class="small subtle">${S.settings.dailyMinutes} minutes planned daily</span></div><div class="home-grid"><div class="card"><div class="eyebrow">${recent?'CONTINUE LEARNING':'GET STARTED'}</div><h3>${recent?esc(recent.title):'Bring your lessons into Studora'}</h3><p>${recent?'Pick up your last discussion, with the same lesson and sources.':'Start with a textbook chapter or worksheet. Add its numbered lessons and learn from each example.'}</p>${btn(recent?'Continue conversation '+icon('arrow-right'):'Choose Math '+icon('arrow-right'),recent?'resume':'subject','primary',`data-id="${recent?.id||S.subjects.find(s=>s.name==='Math')?.id||S.subjects[0]?.id}"`)}</div><div class="card"><div class="eyebrow">UPCOMING EXAMS</div>${exams.slice(0,3).map(examRow).join('')||`<h3>No exam dates yet</h3><p>Add dates and included lessons to see what needs attention first.</p>${btn('Add your first exam','exam','link-button')}`}</div></div>${exams.length?`<div class="section-head"><h2>Suggested next step</h2></div><div class="card"><h3>${esc(S.subjects.find(s=>s.id===exams[0].subjectId)?.name||'Subject')} · ${esc(exams[0].title)}</h3><p>${days(exams[0].date)===0?'Exam today':`${days(exams[0].date)} days until this exam`}. ${esc(exams[0].scope||'Review the included lessons and identify what still feels unclear.')} This suggestion is based on your nearest exam date; readiness has not been assumed.</p>${btn('Open subject','subject','secondary',`data-id="${exams[0].subjectId}"`)}</div>`:''}<div class="section-head"><h2>Your subjects</h2>${btn(icon('plus')+'Add subject','add-subject','link-button')}</div><div class="subject-grid">${S.subjects.map(s=>`<button class="subject-card" data-action="subject" data-id="${s.id}" style="--subject:${esc(s.color)}">${icon(s.icon)}<span class="subject-name">${esc(s.name)}</span><small>${S.lessons.filter(l=>l.subjectId===s.id).length} lessons · ${S.sources.filter(x=>x.subjectId===s.id).length} sources</small></button>`).join('')}</div></div></div>`}
function examRow(e){const s=S.subjects.find(x=>x.id===e.subjectId);return `<div class="exam-row"><div><h3>${esc(s?.name)} · ${esc(e.title)}</h3><small>${esc(e.date)}${e.scope?' · '+esc(e.scope):''}</small></div><div class="row"><span class="exam-time">${days(e.date)===0?'Today':days(e.date)+' days'}</span>${btn(icon('pencil'),'exam','icon-button',`data-id="${e.id}" aria-label="Edit exam"`)}</div></div>`}
function renderSubject(main){const l=lesson(),c=chat();main.innerHTML=header(tab==='Tutor'?(c?.title||l?.title||'Your tutor'):tab,subject()?.name+(l?' / '+l.chapter+' / '+l.number:''),`${btn(icon('panel-right'),'context','icon-button','aria-label="Open lesson context" title="Lesson context"')}${c?btn(icon('ellipsis'),'chat-menu','icon-button','aria-label="Chat options"'):''}`)+`<nav class="tabs" aria-label="Subject workspace">${S.settings.tabs.map(t=>btn(t,'tab',t===tab?'active':'',`data-tab="${t}"`)).join('')}</nav>`;
if(tab==='Tutor')renderTutor(main);if(tab==='Lessons')renderLessons(main);if(tab==='Notebook')renderNotebook(main);if(tab==='Sources')renderSources(main);if(tab==='Practice')renderPractice(main)}
function renderTutor(main){const c=chat();const l=lesson();const arabic=subject()?.name==='Arabic';const messages=c?.messages||[];main.insertAdjacentHTML('beforeend',`<div class="chat-scroll"><div class="conversation">${messages.length?messages.map((m,i)=>renderMessage(m,i)).join(''):`<div class="empty-state"><div>${icon('sparkles').replace('<i ','<i class="empty-icon" ')}</div><div class="eyebrow">${l?'LESSON '+esc(l.number):esc(subject()?.name)+' TUTOR'}</div><h2>${l?'Let’s understand '+esc(l.title)+'.':'What would you like to understand?'}</h2><p>${l?'Choose an example, explore a concept, or ask about the step that stopped making sense.':'Add your sources or start a conversation. Your tutor can explain, illustrate, and work through a lesson with you.'}</p><div class="prompt-suggestions">${btn('Teach me this lesson from the beginning','suggest','','data-prompt="Teach me this lesson from the beginning. Explain in short sections and help me understand why."')}${btn('Help me find where I got lost','suggest','','data-prompt="Help me find where I am getting confused in this lesson. Ask me a small diagnostic question first."')}${btn('Explain a worked example','suggest','','data-prompt="Help me understand a worked example from my selected sources. Ask which example if none is selected."')}${btn('Let me explain it back to you','suggest','','data-prompt="Let me explain this concept back to you. Listen to my explanation and identify any gaps."')}</div>${subject()?.name==='Math'?`<div class="empty-actions">${btn(icon('shapes')+'Open geometry workspace','geometry','secondary')}</div>`:''}</div>`}${busy?'<div class="thinking"><span class="spinner"></span><span id="thinking-label">Thinking through your lesson…</span></div>':''}${error?`<div class="error-inline">${esc(error)}<div>${btn('Retry last message','retry','link-button')}</div></div>`:''}<div id="geometry-host"></div></div></div><div class="composer-wrap"><div class="composer-inner"><div class="context-chips"><select id="lesson-select" aria-label="Lesson"><option value="">No lesson selected</option>${S.lessons.filter(x=>x.subjectId===subjectId).map(x=>`<option value="${x.id}" ${x.id===lessonId?'selected':''}>${esc(x.number+' '+x.title)}</option>`).join('')}</select>${l?.examples?.length?`<select id="example-select" aria-label="Example"><option value="">All examples</option>${l.examples.map(x=>`<option value="${esc(x)}" ${example===x?'selected':''}>Example ${esc(x)}</option>`).join('')}</select>`:''}<select id="language-select" aria-label="Tutor explanation language"><option ${S.settings.tutorLanguage==='English'?'selected':''}>English</option><option ${S.settings.tutorLanguage==='Arabic'?'selected':''}>Arabic</option></select>${btn(icon('files')+activeSources.length+' sources','context','chip')}<span class="chip">${esc(S.settings.effort==='default'?'Model default':S.settings.effort+' reasoning')}</span></div><div class="composer"><textarea id="prompt" placeholder="Ask about a concept, a step, or an example…" aria-label="Message your tutor" ${busy?'disabled':''}>${esc(draft)}</textarea><div class="composer-bottom"><div class="row">${btn(icon('paperclip'),'import','icon-button','aria-label="Add source or photo" title="Add source or photo"')}${btn(icon('pencil-line'),'whiteboard','icon-button','aria-label="Draw your working" title="Draw your working"')}<small>${arabic?'Arabic questions · '+esc(S.settings.tutorLanguage)+' explanations':'Enter to send · Shift + Enter for a new line'}</small></div>${btn(icon(busy?'square':'arrow-up'),busy?'stop':'send','primary',`aria-label="${busy?'Stop response':'Send message'}"`)}</div></div><div class="composer-footer"><span>${connected?'Connected to your OpenAI API account':'Connect AI in Settings to start tutoring'}</span><span>AI can make mistakes. Check important steps.</span></div></div></div>`);
const textarea=$('#prompt');textarea.oninput=()=>{draft=textarea.value;const c=chat();if(c){c.draft=draft;persist()}};textarea.onkeydown=e=>{if(e.key==='Enter'&&!e.shiftKey){e.preventDefault();send()}};$('#lesson-select').onchange=e=>{lessonId=e.target.value||null;example='';if(chat()){chat().lessonId=lessonId;chat().sourceIds=lesson()?.sourceIds||subjectsSources().map(x=>x.id)}activeSources=chat()?.sourceIds||lesson()?.sourceIds||subjectsSources().map(x=>x.id);persist();render()};if($('#example-select'))$('#example-select').onchange=e=>example=e.target.value;$('#language-select').onchange=e=>{S.settings.tutorLanguage=e.target.value;persist()};mountArtifacts();const scroll=$('.chat-scroll');if(messages.length)scroll.scrollTop=scroll.scrollHeight;mathRender(main)}
function renderMessage(m,i){if(m.role==='user')return `<article class="message user"><div class="message-text" dir="auto">${esc(m.text)}</div></article>`;return `<article class="message assistant"><div class="byline">${icon('sparkles')} STUDORA · ${m.sourceIds?.length?'YOUR SOURCES':'GENERAL EXPLANATION'}</div><div class="message-text" dir="auto" ${m.language==='Arabic'?'lang="ar"':''}>${md(m.text)}</div>${(m.artifacts||[]).map((a,j)=>a.type==='geometry'?`<div class="artifact-geometry" data-message="${i}" data-artifact="${j}"></div>`:a.type==='concept'?`<div class="concept-artifact" data-message="${i}" data-artifact="${j}"></div>`:a.type==='calculation'?`<div class="tool-banner">${icon('check')} Numerical check: ${esc(a.expression)} = ${esc(a.result)}</div>`:a.type==='practice'?`<div class="tool-banner">${icon('notebook-pen')} Practice ready${a.example?' · Example '+esc(a.example):''} ${btn('Open practice','tab','link-button','data-tab="Practice"')}</div>`:'').join('')}<div class="message-tools">${btn(icon('bookmark')+'Save to notebook','save-message','',`data-index="${i}"`)}${btn(icon('copy')+'Copy','copy-message','',`data-index="${i}"`)}${btn('Explain another way','re-explain','',`data-index="${i}"`)}</div></article>`}
function mountArtifacts(){document.querySelectorAll('.concept-artifact').forEach(host=>{const m=chat()?.messages[Number(host.dataset.message)],a=m?.artifacts?.[Number(host.dataset.artifact)];if(!a)return;const draw=()=>{const index=a.selected||0;host.innerHTML=`<div class="concept-card"><h3>${esc(a.title)}</h3><div class="concept-tabs">${a.steps.map((step,n)=>`<button type="button" data-step="${n}" class="${index===n?'selected':''}" aria-pressed="${index===n}"><span>${n+1}</span>${esc(step.label)}</button>`).join('')}</div><div class="concept-detail message-text" dir="auto" aria-live="polite">${md(a.steps[index]?.explanation||'')}</div></div>`;mathRender(host);host.querySelectorAll('[data-step]').forEach(button=>button.onclick=()=>{a.selected=Number(button.dataset.step);draw();persist()})};draw()});document.querySelectorAll('.artifact-geometry').forEach(host=>{const m=chat()?.messages[Number(host.dataset.message)],a=m?.artifacts?.[Number(host.dataset.artifact)];if(a)Geometry.mount(host,a.kind,snapshot=>{a.snapshot=snapshot;persist()},a.snapshot)})}
function newChat(){const c={id:id(),subjectId,lessonId,title:lesson()?lesson().number+' · New conversation':'New conversation',messages:[],sourceIds:lesson()?.sourceIds||subjectsSources().map(x=>x.id),createdAt:new Date().toISOString(),updatedAt:new Date().toISOString(),pinned:false,archived:false,tags:[],folder:'',draft:''};S.chats.push(c);chatId=c.id;activeSources=[...c.sourceIds];draft='';error='';tab='Tutor';persist();return c}
async function send(promptOverride,retry=false){if(busy)return;const text=(promptOverride??$('#prompt')?.value??draft).trim();if(!text){$('#prompt')?.focus();return}if(!connected){toast('Connect your OpenAI API account in Settings first.');return}if(!S.settings.model){toast('Choose your model in Settings → AI connection.');return}let c=chat()||newChat();if(!retry){c.messages.push({role:'user',text,createdAt:new Date().toISOString()});if(c.messages.length===1)c.title=text.slice(0,55);c.updatedAt=new Date().toISOString()}draft='';c.draft='';error='';busy=true;tab='Tutor';render();const targetChatId=c.id;try{await flush();const out=await api.ask({subjectId:c.subjectId,lessonId:c.lessonId,chatId:c.id,prompt:text,sourceIds:activeSources,example,language:S.settings.tutorLanguage});c=S.chats.find(x=>x.id===targetChatId);c.messages.push({role:'assistant',text:out.text,artifacts:out.artifacts,usage:out.usage,sourceIds:out.sourceIds,language:S.settings.tutorLanguage,createdAt:new Date().toISOString()});c.updatedAt=new Date().toISOString();S.usage.input+=out.usage.input;S.usage.output+=out.usage.output;sound(true);}catch(e){error=e.message.includes('aborted')?'Response stopped. Your question is saved.':e.message;}finally{busy=false;persist();render()}}
function renderLessons(main){const lessons=S.lessons.filter(x=>x.subjectId===subjectId);const l=lesson();main.insertAdjacentHTML('beforeend',`<div class="content"><div class="toolbar"><p>Chapters, numbered lessons, and the examples inside them.</p>${btn(icon('plus')+'Add lesson','add-lesson','primary')}</div>${l?`<div class="lesson-detail"><div class="card"><div class="eyebrow">${esc(l.chapter)} · LESSON ${esc(l.number)}</div><h3>${esc(l.title)}</h3><p>${esc(l.description||'Choose an example to study with your tutor. You can edit this lesson anytime.')}</p><div class="row">${btn('Start learning '+icon('arrow-right'),'learn-lesson','primary',`data-id="${l.id}"`)}${btn('Edit lesson','edit-lesson','secondary',`data-id="${l.id}"`)}</div></div><div class="section-head"><h2>Worked examples</h2></div><div class="example-grid">${(l.examples||[]).map(e=>`<button class="example-card" data-action="learn-example" data-example="${esc(e)}"><strong>Example ${esc(e)}</strong><span>Understand the method, explore the diagram, then try related practice.</span></button>`).join('')||'<p class="subtle">Add example numbers in Edit lesson.</p>'}</div>${subject()?.name==='Math'?btn(icon('shapes')+'Open geometry workspace','geometry','secondary'):''}<div id="geometry-host"></div></div>`:`<div class="stack">${lessons.map(x=>`<div class="card lesson-card"><div><div class="number">${esc(x.chapter)} · ${esc(x.number)}</div><h3>${esc(x.title)}</h3><p>${x.examples?.length||0} examples · ${x.sourceIds?.length||0} sources</p></div>${btn('Open '+icon('arrow-right'),'lesson','secondary',`data-id="${x.id}"`)}</div>`).join('')||`<div class="empty-state"><h2>Follow your book, lesson by lesson.</h2><p>Add a chapter, a lesson number such as 2.1, and its worked examples. Every subject can use its own structure.</p>${btn('Add your first lesson','add-lesson','primary')}</div>`}</div>`}</div>`)}
function renderNotebook(main){const notes=S.notes.filter(x=>x.subjectId===subjectId);if(!notes.some(n=>n.id===noteId))noteId=notes[0]?.id||null;const n=notes.find(x=>x.id===noteId);main.insertAdjacentHTML('beforeend',`<div class="content"><div class="toolbar"><p>Your notes, with useful explanations saved from chats.</p><div class="row">${btn(icon('download')+'Export','export-notes','secondary')}${btn(icon('plus')+'New note','new-note','primary')}</div></div>${n?`<div class="note-editor"><div class="notes-list">${notes.map(x=>btn(esc(x.title||'Untitled note'),'note',x.id===noteId?'active':'',`data-id="${x.id}"`)).join('')}</div><div class="note-fields"><input id="note-title" class="note-title" value="${esc(n.title)}" aria-label="Note title"><textarea id="note-body" class="note-body" dir="auto" aria-label="Note content">${esc(n.body)}</textarea><div class="row"><small class="subtle">Saved automatically on this computer.</small>${n.chatId?btn('Original conversation','chat','link-button',`data-id="${n.chatId}"`):''}${btn(icon('trash-2')+'Delete note','delete-note','link-button danger',`data-id="${n.id}"`)}</div></div></div>`:`<div class="empty-state"><h2>Keep the explanations that clicked.</h2><p>Write your own notes or save a tutor response. Everything stays editable.</p>${btn('Create a note','new-note','primary')}</div>`}</div>`);if(n){$('#note-title').oninput=e=>{n.title=e.target.value;persist()};$('#note-body').oninput=e=>{n.body=e.target.value;persist()}}}
function renderSources(main){const sources=subjectsSources();main.insertAdjacentHTML('beforeend',`<div class="content"><div class="toolbar"><p>PDFs, Word documents, photos, and text transcripts.</p><div class="row">${btn('Disabled sources','disabled-sources','secondary')}${btn(icon('clipboard')+'Paste text / transcript','paste-source','secondary')}${btn(icon('upload')+(importing?'Importing…':'Add sources'),'import','primary',importing?'disabled':'')}</div></div><div class="source-list">${sources.map(src=>`<div class="card source-card"><div class="row" style="align-items:flex-start"><div class="source-icon">${icon(src.status==='image'?'image':'file-text')}</div><div><h3>${esc(src.name)}</h3><div class="source-meta">${src.status==='image'?'Photo · interpreted by your vision-capable model':src.status==='scan'?'Scanned PDF · sent to a vision-capable model when selected':src.status==='needs-review'?'Could not extract text · review this file':src.pages.length+(src.ext==='.pdf'?' pages':' text sections')}${src.missing?' · Original file missing':''}</div><label style="margin-top:10px"><input type="checkbox" data-source-check="${src.id}" ${activeSources.includes(src.id)?'checked':''}>Use in tutor context</label></div></div><div class="row">${btn(icon('eye'),'view-source','icon-button',`data-id="${src.id}" aria-label="View ${esc(src.name)}"`)}${btn(icon('external-link'),'open-source','icon-button',`data-id="${src.id}" aria-label="Open original file"`)}${btn(icon('trash-2'),'remove-source','icon-button danger',`data-id="${src.id}" aria-label="Remove source from active use"`)}</div></div>`).join('')||`<div class="empty-state"><h2>Your materials are the starting point.</h2><p>Bring a textbook, teacher slides saved as PDF, worksheets, or photos. Your tutor will reference selected material and label general explanations separately.</p>${btn('Add your first source','import','primary')}</div>`}</div>`)}
function practiceItems(){return S.chats.filter(c=>c.subjectId===subjectId).flatMap(c=>c.messages.flatMap((m,mi)=>(m.artifacts||[]).map((a,ai)=>({...a,key:c.id+':'+mi+':'+ai,chatId:c.id})).filter(a=>a.type==='practice')))}
function renderPractice(main){const items=practiceItems().reverse();main.insertAdjacentHTML('beforeend',`<div class="content"><div class="toolbar"><p>Practice the method from your selected lesson and example.</p><div class="row">${btn('Review mistakes','review-mistakes','secondary')}${btn(icon('plus')+'Generate related practice','generate-practice','primary')}</div></div>${items.map(a=>{const attempt=S.attempts.find(x=>x.key===a.key);return `<div class="card practice-card"><div class="row"><span class="eyebrow">${a.example?'BASED ON EXAMPLE '+esc(a.example):'ORIGINAL PRACTICE'}</span><span class="badge">${a.verified?'Numerical tool used · review reasoning':'AI-generated · answer needs review'}</span></div><div class="practice-question ${subject()?.name==='Arabic'?'arabic':''}" dir="auto" ${subject()?.name==='Arabic'?'lang="ar"':''}>${md(a.question)}</div>${a.sourceId?btn('Source · page '+a.page,'citation','link-button',`data-source="${a.sourceId}" data-page="${a.page}"`):''}<textarea class="practice-answer" data-practice="${esc(a.key)}" aria-label="Your answer" placeholder="Try it independently. Include your working…" dir="auto">${esc(attempt?.answer||'')}</textarea><div class="row">${btn('Show answer & explanation','reveal-practice','secondary',`data-key="${esc(a.key)}"`)}${btn('Discuss my working with tutor','discuss-practice','link-button',`data-key="${esc(a.key)}"`)}</div><div class="practice-solution" data-solution="${esc(a.key)}" hidden><div class="message-text" dir="auto">${md(a.answer+'\n\n'+a.explanation)}</div><p class="small subtle">How did this attempt feel? This is your reflection, not an automatic mastery score.</p><div class="row">${btn('I understood','rate-practice','secondary',`data-key="${esc(a.key)}" data-rating="understood"`)}${btn('Still unsure','rate-practice','secondary',`data-key="${esc(a.key)}" data-rating="unsure"`)}</div></div>${attempt?.rating?`<p class="small subtle">Your reflection: ${esc(attempt.rating)}</p>`:''}</div>`}).join('')||`<div class="empty-state"><h2>Understanding first. Practice next.</h2><p>Choose a lesson and its sources, then ask your tutor for practice based on a particular example. Answers are kept hidden while you try.</p>${btn('Choose a lesson','tab','primary','data-tab="Lessons"')}</div>`}</div>`);document.querySelectorAll('[data-practice]').forEach(t=>t.oninput=()=>{let a=S.attempts.find(x=>x.key===t.dataset.practice);if(!a){a={id:id(),key:t.dataset.practice,subjectId,answer:'',createdAt:new Date().toISOString()};S.attempts.push(a)}a.answer=t.value;persist()});mathRender(main)}
function renderSettings(main){const st=S.settings;main.innerHTML=header('Make it yours','Settings')+`<div class="content"><div class="settings-layout"><section class="settings-section" id="updates-settings"><h2>Updates</h2><p class="small subtle">Studora ${esc(updateState.currentVersion)} · Stable releases from ${esc(updateState.repository||'your connected repository')}.</p>${btn(icon('download')+'Check for updates','updates','secondary')}<p class="small subtle">Studora checks when you open it. You choose when to download and restart. Your study workspace stays on this computer.</p></section><section class="settings-section" id="appearance"><h2>Appearance</h2><div class="fields-grid"><div class="field"><label for="theme">Theme</label><select id="theme"><option value="light" ${st.theme==='light'?'selected':''}>Light · off-white & forest green</option><option value="dark" ${st.theme==='dark'?'selected':''}>Dark · near-black & muted green</option><option value="system" ${st.theme==='system'?'selected':''}>Follow Windows</option></select></div><div class="field"><label for="sidebar-width">Sidebar width</label><input id="sidebar-width" type="range" min="190" max="360" value="${st.sidebarWidth}"><small id="width-label">${st.sidebarWidth}px · also draggable</small></div></div><div class="settings-row"><div><label for="sounds">Quiet interaction sounds</label><p>Soft selection and completion cues. Mute is always available in the rail.</p></div><input id="sounds" type="checkbox" ${st.sound?'checked':''}></div><div class="small subtle">Reduced motion follows your Windows/browser preference.</div></section><section class="settings-section" id="connection"><h2>AI connection</h2><p class="small subtle">Use your separate OpenAI API account. Selected text, messages, and images are sent to OpenAI when you ask the tutor. Your key is encrypted using Windows secure storage.</p><div class="row" style="margin:18px 0"><span class="badge"><span class="status-dot"></span>${connected?(connectionPersistent?'Key saved securely':'Session-only connection'):'Not connected'}</span>${btn(connected?'Change API key':'Connect API key','connect-key','primary')}${connected?btn('Disconnect','disconnect-key','secondary'):''}${connected?btn('Refresh available models','load-models','secondary'):''}</div><div class="fields-grid"><div class="field"><label for="model-name">Model ID</label><input id="model-name" value="${esc(st.model)}" placeholder="Choose from your account or enter a model ID" list="models-list"><datalist id="models-list"></datalist><small>Only models your API account can access will work.</small></div><div class="field"><label for="reasoning">Reasoning effort</label><select id="reasoning">${['default','low','medium','high','xhigh','max'].map(x=>`<option value="${x}" ${st.effort===x?'selected':''}>${x==='default'?'Model default':x}</option>`).join('')}</select><small>Support depends on the model. Use Model default if a setting is rejected.</small></div><div class="field"><label for="max-tokens">Response token limit</label><input id="max-tokens" type="number" min="1000" max="24000" step="1000" value="${st.maxOutputTokens}"><small>Reasoning also uses the output budget. Higher limits can cost more.</small></div><div class="field"><label for="token-guard">Monthly token guard</label><input id="token-guard" type="number" min="0" step="10000" value="${st.monthlyTokenLimit||0}"><small>0 disables the guard. Blocks new requests after the limit; not a currency billing cap.</small></div></div><p class="small subtle">Recorded usage this month: ${Number(S.usage.input).toLocaleString()} input + ${Number(S.usage.output).toLocaleString()} output tokens. Set provider billing limits separately.</p></section><section class="settings-section" id="learning"><h2>Learning preferences</h2><div class="fields-grid"><div class="field"><label for="tutor-language">Tutor explanation language</label><select id="tutor-language"><option ${st.tutorLanguage==='English'?'selected':''}>English</option><option ${st.tutorLanguage==='Arabic'?'selected':''}>Arabic</option></select><small>Arabic practice questions stay Arabic. You can also switch in a conversation.</small></div><div class="field"><label for="daily-minutes">Daily study time</label><input id="daily-minutes" type="number" min="5" max="480" value="${st.dailyMinutes}"></div></div><p class="small subtle">Teaching starts with manageable explanations and adapts through follow-up questions. Ask for a deeper explanation, guided steps, or a complete lesson anytime.</p></section><section class="settings-section" id="organization"><h2>Subjects & organization</h2><div class="stack">${S.subjects.map(s=>`<div class="settings-row"><div class="row"><input aria-label="${esc(s.name)} color" type="color" value="${esc(s.color)}" data-subject-color="${s.id}"><span>${esc(s.name)}</span></div>${btn('Rename','rename-subject','secondary',`data-id="${s.id}"`)}</div>`).join('')}</div>${btn(icon('plus')+'Add subject','add-subject','link-button')}<hr class="divider"><label class="small">Tab order · click a tab to move it one place left</label><div class="tab-order">${st.tabs.map(t=>btn(esc(t)+icon('chevron-left'),'move-tab','',`data-tab="${t}"`)).join('')}</div></section><section class="settings-section" id="data"><h2>Your data</h2><p class="small subtle">Chats, notes, settings, and original imported files are stored on this computer. The JSON backup includes extracted source text; copy the sources folder as well to preserve originals. API credentials are excluded.</p><div class="row">${btn(icon('download')+'Export backup','backup','secondary')}${btn(icon('upload')+'Restore backup','restore','secondary')}${btn(icon('folder-open')+'Open data folder','open-data','secondary')}</div></section></div></div>`;
const bind=(selector,prop,number=false)=>{$(selector).onchange=e=>{st[prop]=number?Number(e.target.value):e.target.value;persist();applyTheme();icons()}};bind('#theme','theme');bind('#model-name','model');bind('#reasoning','effort');bind('#max-tokens','maxOutputTokens',true);bind('#token-guard','monthlyTokenLimit',true);bind('#tutor-language','tutorLanguage');bind('#daily-minutes','dailyMinutes',true);$('#sidebar-width').oninput=e=>{st.sidebarWidth=Number(e.target.value);$('#width-label').textContent=st.sidebarWidth+'px · also draggable';applyTheme();persist()};$('#sounds').onchange=e=>{st.sound=e.target.checked;applyTheme();persist();icons()};document.querySelectorAll('[data-subject-color]').forEach(input=>input.oninput=()=>{S.subjects.find(s=>s.id===input.dataset.subjectColor).color=input.value;renderRail();icons();persist()})}

function renderUpdateButton(){const button=$('#updates'),ready=['available','downloaded'].includes(updateState.status);button.classList.toggle('update-ready',ready);button.querySelector('.update-dot').hidden=!ready;button.title=button.ariaLabel=updateState.status==='downloaded'?'Update ready to install':ready?'Update available':'Check for updates'}
function updateDialog(){
const u=updateState,d=$('#modal'),titles={idle:'Keep Studora up to date',checking:'Checking for updates',up_to_date:'You’re up to date',available:'A new version is available',downloading:'Downloading your update',downloaded:'Your update is ready',installing:'Restarting Studora',error:'Could not check for updates',development:'Updates work in the installed app',unconfigured:'No release repository connected'};
let description={idle:'Check for the latest stable version of Studora.',checking:'Looking for a new stable release on GitHub.',up_to_date:'You have the latest stable release.',available:'Download the update, then restart whenever you are ready.',downloading:'You can close this panel and keep studying while it downloads.',downloaded:'Restart to install. Your chats, notes, settings, and study files stay in place.',installing:'Your workspace has been saved. Studora will reopen after installation.',error:u.error,development:'Install the Windows setup to check and install releases.',unconfigured:'This build needs a GitHub release repository.'}[u.status]||'';
const working=['checking','downloading','installing'].includes(u.status);
let action=u.status==='available'?btn('Download update','update-download','primary'):u.status==='downloaded'?btn('Restart and install','update-install','primary'):!working&&!['development','unconfigured'].includes(u.status)?btn(u.status==='error'?'Try again':'Check again','update-check','primary'):'';
$('#modal-body').innerHTML='<div class="eyebrow">STUDORA UPDATES</div><h2>'+esc(titles[u.status]||titles.idle)+'</h2><p>'+esc(description)+'</p><div class="update-version"><span>Installed <strong>'+esc(u.currentVersion)+'</strong></span>'+(u.version?'<span>'+icon('arrow-right')+' Latest <strong>'+esc(u.version)+'</strong></span>':'')+'</div>'+(u.status==='downloading'?'<progress class="update-progress" max="100" value="'+u.percent+'" aria-label="Update download progress"></progress><p class="small subtle">'+Math.round(u.percent)+'% downloaded</p>':'')+(u.status==='checking'?'<div class="row small subtle"><span class="spinner"></span>Checking GitHub Releases…</div>':'')+'<p class="small subtle">'+esc(u.repository||'')+'</p><div class="modal-actions">'+btn('Close','close-modal','secondary')+action+'</div>';
d.dataset.updates='true';if(!d.open)d.showModal();icons();
}
function receiveUpdate(status){updateState=status;renderUpdateButton();if($('#modal').open&&$('#modal').dataset.updates)updateDialog()}
api.onUpdateStatus(receiveUpdate);
$('#modal').addEventListener('close',()=>{delete $('#modal').dataset.updates});

function modal(title,body,actions=''){const d=$('#modal');delete d.dataset.updates;$('#modal-body').innerHTML=`<h2>${esc(title)}</h2>${body}<div class="modal-actions">${btn('Cancel','close-modal','secondary')}${actions}</div>`;d.showModal();icons()}
function closeModal(){$('#modal').close()}
function field(label,name,value='',type='text',extra=''){return `<div class="field"><label for="f-${name}">${esc(label)}</label><input id="f-${name}" name="${name}" type="${type}" value="${esc(value)}" ${extra}></div>`}
function editLesson(lid){const l=S.lessons.find(x=>x.id===lid);modal(l?'Edit lesson':'Add a lesson',`<p>Match your textbook structure. Numbers and example labels are editable.</p><form id="lesson-form" class="modal-form">${field('Chapter','chapter',l?.chapter||'Chapter 1')}${field('Lesson number','number',l?.number||'1.1')}${field('Lesson title','title',l?.title||'')}${field('Example numbers, separated by commas','examples',l?.examples?.join(', ')||'1, 2, 3, 4')}<div class="fields-grid">${field('PDF start page (optional)','page-start',l?.pageStart||'','number','min="1"')}${field('PDF end page (optional)','page-end',l?.pageEnd||'','number','min="1"')}</div><div class="field"><label>Sources for this lesson</label>${subjectsSources().map(src=>`<label class="source-check"><input type="checkbox" name="lesson-source" value="${src.id}" ${l?.sourceIds?.includes(src.id)?'checked':''}>${esc(src.name)}</label>`).join('')||'<small>Add sources in the Sources tab first, or link them later.</small>'}</div></form>`,`${l?btn('Delete lesson','delete-lesson','link-button danger',`data-id="${l.id}"`):''}${btn('Save lesson','save-lesson','primary',`data-id="${lid||''}"`)}`)}
function editExam(eid){const e=S.exams.find(x=>x.id===eid);modal(e?'Edit exam':'Add an exam',`<form id="exam-form" class="modal-form"><div class="field"><label for="exam-subject">Subject</label><select id="exam-subject">${S.subjects.map(s=>`<option value="${s.id}" ${(e?.subjectId||subjectId)===s.id?'selected':''}>${esc(s.name)}</option>`).join('')}</select></div>${field('Exam name','exam-title',e?.title||'Midterm')}${field('Date','exam-date',e?.date||today(),'date')}${field('Included lessons / chapters','exam-scope',e?.scope||'')}</form>`,`${e?btn('Delete','delete-exam','link-button danger',`data-id="${e.id}"`):''}${btn('Save exam','save-exam','primary',`data-id="${eid||''}"`)}`)}
function searchDialog(){modal('Search your workspace',`<div class="field"><input id="search-input" placeholder="Search chats, lessons, notes, and source text…" aria-label="Search"></div><div class="search-results" id="search-results"></div>`);$('#search-input').focus();$('#search-input').oninput=e=>{const q=e.target.value.toLowerCase().trim();if(!q){$('#search-results').innerHTML='';return}const results=[...S.chats.filter(c=>(c.title+' '+c.tags.join(' ')+' '+c.folder+' '+c.messages.map(m=>m.text).join(' ')).toLowerCase().includes(q)).map(c=>({type:'chat',id:c.id,sid:c.subjectId,title:c.title})),...S.lessons.filter(l=>(l.title+' '+l.number).toLowerCase().includes(q)).map(l=>({type:'lesson',id:l.id,sid:l.subjectId,title:l.number+' '+l.title})),...S.notes.filter(n=>(n.title+' '+n.body).toLowerCase().includes(q)).map(n=>({type:'note',id:n.id,sid:n.subjectId,title:n.title})),...S.sources.filter(s=>(s.name+' '+s.pages.map(p=>p.text).join(' ')).toLowerCase().includes(q)).map(s=>({type:'view-source',id:s.id,sid:s.subjectId,title:s.name}))];$('#search-results').innerHTML=results.slice(0,35).map(r=>btn(`${esc(r.title)}<small>${esc(S.subjects.find(x=>x.id===r.sid)?.name)} · ${esc(r.type)}</small>`,'search-result','',`data-type="${r.type}" data-id="${r.id}" data-subject="${r.sid}"`)).join('')||'<p class="subtle">No results yet.</p>'}}
async function renderContext(){const panel=$('#context');panel.hidden=false;const src=S.sources.find(s=>s.id===contextSource);panel.innerHTML=`<div class="context-heading"><h3>${src?'Source':'Lesson context'}</h3>${btn(icon('x'),'close-context','icon-button','aria-label="Close context panel"')}</div>${src?`<h3 style="font-size:13px">${esc(src.name)}</h3><div class="row">${btn('Open original','open-source','link-button',`data-id="${src.id}"`)}${btn('Back to context','context-back','link-button')}</div>${src.pages?.length?`<div class="field"><label for="context-page">${src.ext==='.pdf'?'Page':'Text section'}</label><select id="context-page">${src.pages.map(p=>`<option value="${p.page}" ${p.page===contextPage?'selected':''}>${p.page}</option>`).join('')}</select></div><div class="source-preview" dir="auto"><small>${src.ext==='.pdf'?'PAGE':'SECTION'} ${contextPage}</small>${esc(src.pages.find(p=>p.page===contextPage)?.text||'No extracted text. Open the original file to review this page.')}</div>`:''}${src.status==='image'?'<img id="context-image" class="source-preview-image" alt="Imported study image">':''}`:`<div class="eyebrow">ACTIVE LESSON</div><p>${lesson()?esc(lesson().number+' '+lesson().title):'No lesson selected'}</p><hr class="divider"><div class="eyebrow">TUTOR SOURCES</div>${subjectsSources().map(s=>`<label class="source-check"><input type="checkbox" data-source-check="${s.id}" ${activeSources.includes(s.id)?'checked':''}><span>${esc(s.name)}<br>${btn('View','view-source','link-button',`data-id="${s.id}"`)}</span></label>`).join('')||'<p class="small subtle">Add your study materials to ground explanations in your curriculum.</p>'}<p class="small subtle">Only selected sources are included. With none selected, your tutor uses general knowledge.</p>`}`;if($('#context-page'))$('#context-page').onchange=e=>{contextPage=Number(e.target.value);renderContext()};if(src?.status==='image'){try{$('#context-image').src=await api.sourceImage(src.id)}catch(e){toast(e.message)}}icons()}
async function importFiles(){if(importing)return;importing=true;try{await flush();const sources=await api.importSources(subjectId);for(const src of sources){if(!S.sources.some(x=>x.id===src.id))S.sources.push(src);activeSources.push(src.id)}if(chat())chat().sourceIds=[...activeSources];persist();toast(sources.length?`${sources.length} source${sources.length===1?'':'s'} added.`:'Import cancelled.');}catch(e){toast('Import failed: '+e.message)}finally{importing=false;render()}}
document.addEventListener('change',e=>{const check=e.target.dataset.sourceCheck;if(check){activeSources=e.target.checked?[...new Set([...activeSources,check])]:activeSources.filter(x=>x!==check);if(chat())chat().sourceIds=[...activeSources];persist();if(tab==='Tutor')render();}});
document.addEventListener('click',async e=>{const a=e.target.closest('[data-action]');if(!a)return;const action=a.dataset.action;try{switch(action){
case 'home':view='home';contextSource=null;$('#context').hidden=true;render();persist();break;
case 'subject':openSubject(a.dataset.id);break;
case 'updates':updateDialog();receiveUpdate(await api.checkUpdates());break;
case 'update-check':receiveUpdate(await api.checkUpdates());break;
case 'update-download':receiveUpdate(await api.downloadUpdate());break;
case 'update-install':if(busy){toast('Finish or stop the current explanation before restarting.');break}draft=$('#prompt')?.value||draft;if(chat())chat().draft=draft;await flush();receiveUpdate(await api.installUpdate());break;
case 'settings':draft=$('#prompt')?.value||draft;view='settings';$('#context').hidden=true;render();persist();break;
case 'settings-anchor':$('#'+a.dataset.anchor)?.scrollIntoView({behavior:matchMedia('(prefers-reduced-motion: reduce)').matches?'instant':'smooth'});break;
case 'mute':S.settings.sound=!S.settings.sound;applyTheme();icons();persist();break;
case 'add-subject':modal('Add a subject',`<form class="modal-form">${field('Subject name','subject-name')}${field('Subject color','subject-color','#4b775a','color')}</form>`,btn('Add subject','save-subject','primary'));break;
case 'save-subject':{const name=$('#f-subject-name').value.trim();if(!name)return toast('Enter a subject name.');const s={id:id(),name,color:$('#f-subject-color').value,icon:'book-open'};S.subjects.push(s);closeModal();openSubject(s.id);break;}
case 'rename-subject':{const s=S.subjects.find(x=>x.id===a.dataset.id);modal('Rename subject',field('Subject name','rename',s.name),btn('Save','save-rename-subject','primary',`data-id="${s.id}"`));break;}
case 'save-rename-subject':{const name=$('#f-rename').value.trim();if(!name)return;S.subjects.find(x=>x.id===a.dataset.id).name=name;closeModal();persist();render();break;}
case 'subject-menu':modal('Subject options',`<p>${esc(subject().name)}</p>`,btn('Rename','rename-subject','secondary',`data-id="${subjectId}"`));break;
case 'tab':draft=$('#prompt')?.value||draft;tab=a.dataset.tab;error='';render();persist();break;
case 'sources-tab':tab='Sources';render();break;
case 'new-chat':newChat();render();break;
case 'chat':case 'resume':{const c=S.chats.find(x=>x.id===a.dataset.id);if(!c)return;closeModal();subjectId=c.subjectId;view='subject';chatId=c.id;lessonId=c.lessonId;activeSources=c.sourceIds||[];draft=c.draft||'';tab='Tutor';render();persist();break;}
case 'add-lesson':editLesson();break;
case 'edit-lesson':editLesson(a.dataset.id);break;
case 'save-lesson':{const title=$('#f-title').value.trim(),number=$('#f-number').value.trim();if(Number($('#f-page-end').value)&&Number($('#f-page-start').value)>Number($('#f-page-end').value))return toast('Start page must come before end page.');if(!title||!number)return toast('Add a lesson title and number.');let l=S.lessons.find(x=>x.id===a.dataset.id);if(!l){l={id:id(),subjectId};S.lessons.push(l)}Object.assign(l,{title,number,chapter:$('#f-chapter').value.trim()||'Lessons',examples:$('#f-examples').value.split(',').map(x=>x.trim()).filter(Boolean),pageStart:Number($('#f-page-start').value)||null,pageEnd:Number($('#f-page-end').value)||null,sourceIds:[...document.querySelectorAll('[name=lesson-source]:checked')].map(x=>x.value)});lessonId=l.id;activeSources=[...l.sourceIds];closeModal();tab='Lessons';persist();render();break;}
case 'delete-lesson':{const lid=a.dataset.id;S.lessons=S.lessons.filter(x=>x.id!==lid);S.chats.forEach(c=>{if(c.lessonId===lid)c.lessonId=null});if(lessonId===lid)lessonId=null;closeModal();persist();render();toast('Lesson removed. Its conversations were kept.');break;}
case 'lesson':lessonId=a.dataset.id;tab='Lessons';activeSources=lesson()?.sourceIds||[];render();persist();break;
case 'learn-lesson':lessonId=a.dataset.id;newChat();render();break;
case 'learn-example':example=a.dataset.example;newChat();draft=`Please teach me Example ${example} from Lesson ${lesson().number}. Explain the givens, each step, and why the method works.`;render();break;
case 'search':searchDialog();break;
case 'search-result':{closeModal();openSubject(a.dataset.subject);if(a.dataset.type==='chat'){$(`[data-action="chat"][data-id="${a.dataset.id}"]`)?.click()}else if(a.dataset.type==='lesson'){lessonId=a.dataset.id;tab='Lessons';render()}else if(a.dataset.type==='note'){noteId=a.dataset.id;tab='Notebook';render()}else{contextSource=a.dataset.id;contextPage=1;renderContext()}break;}
case 'chat-menu':{const c=chat();modal('Organize conversation',`<form class="modal-form">${field('Name','chat-title',c.title)}${field('Folder','chat-folder',c.folder||'')}${field('Tags, separated by commas','chat-tags',c.tags?.join(', ')||'')}</form>`,btn(c.pinned?'Unpin':'Pin','pin-chat','secondary')+btn('Archive','archive-chat','secondary')+btn('Save','save-chat','primary'));break;}
case 'save-chat':{const c=chat();c.title=$('#f-chat-title').value.trim()||c.title;c.folder=$('#f-chat-folder').value.trim();c.tags=$('#f-chat-tags').value.split(',').map(x=>x.trim()).filter(Boolean);closeModal();persist();render();break;}
case 'pin-chat':chat().pinned=!chat().pinned;closeModal();persist();render();break;
case 'archive-chat':chat().archived=true;chatId=null;closeModal();persist();render();break;
case 'archives':modal('Archived conversations',S.chats.filter(c=>c.subjectId===subjectId&&c.archived).map(c=>`<div class="settings-row"><span>${esc(c.title)}</span>${btn('Restore','unarchive-chat','secondary',`data-id="${c.id}"`)}</div>`).join('')||'<p>No archived chats.</p>');break;
case 'unarchive-chat':S.chats.find(c=>c.id===a.dataset.id).archived=false;closeModal();persist();render();break;
case 'send':send();break;
case 'stop':await api.stop();break;
case 'retry':{const last=chat()?.messages.filter(x=>x.role==='user').at(-1);if(last)send(last.text,true);break;}
case 'suggest':draft=a.dataset.prompt;$('#prompt').value=draft;$('#prompt').focus();break;
case 're-explain':draft='Please explain your previous answer another way, using a simpler example or a visual explanation.';$('#prompt').value=draft;$('#prompt').focus();break;
case 'context':contextSource=null;renderContext();break;
case 'context-back':contextSource=null;renderContext();break;
case 'close-context':$('#context').hidden=true;break;
case 'citation':case 'view-source':contextSource=a.dataset.source||a.dataset.id;contextPage=Number(a.dataset.page)||1;renderContext();break;
case 'open-source':{const src=S.sources.find(s=>s.id===a.dataset.id);if(src.ext==='.txt'&&!src.file){contextSource=src.id;renderContext()}else{const error=await api.openSource(a.dataset.id);if(error)toast(error)}break;}
case 'import':await importFiles();break;
case 'remove-source':{const src=S.sources.find(s=>s.id===a.dataset.id);activeSources=activeSources.filter(x=>x!==src.id);if(chat())chat().sourceIds=[...activeSources];src.retired=true;toast('Source disabled. Its saved text and old citations are preserved.');persist();render();break;}
case 'disabled-sources':modal('Disabled sources',S.sources.filter(s=>s.subjectId===subjectId&&s.retired).map(s=>`<div class="settings-row"><span>${esc(s.name)}</span>${btn('Enable again','enable-source','secondary',`data-id="${s.id}"`)}</div>`).join('')||'<p>No disabled sources.</p>');break;
case 'enable-source':S.sources.find(s=>s.id===a.dataset.id).retired=false;closeModal();persist();render();break;
case 'paste-source':modal('Add text or a video transcript',`<p>Paste your own notes or a transcript. This version uses transcript text rather than fetching or transcribing video.</p><div class="modal-form">${field('Source title','source-title')}<div class="field"><label for="source-text">Text</label><textarea id="source-text" rows="8"></textarea></div></div>`,btn('Save source','save-text-source','primary'));break;
case 'save-text-source':{const text=$('#source-text').value.trim(),name=$('#f-source-title').value.trim();if(!text||!name)return toast('Add a title and text.');const src={id:id(),subjectId,name,ext:'.txt',status:'ready',pages:[{page:1,text}],createdAt:new Date().toISOString()};S.sources.push(src);activeSources.push(src.id);if(chat())chat().sourceIds=[...activeSources];closeModal();persist();render();break;}
case 'new-note':{const n={id:id(),subjectId,title:'Untitled note',body:'',createdAt:new Date().toISOString()};S.notes.push(n);noteId=n.id;tab='Notebook';persist();render();break;}
case 'note':noteId=a.dataset.id;tab='Notebook';render();break;
case 'save-message':{const m=chat().messages[Number(a.dataset.index)];const n={id:id(),subjectId,title:chat().title,body:m.text,chatId,sourceIds:m.sourceIds,createdAt:new Date().toISOString()};S.notes.push(n);persist();toast('Saved to your editable notebook.');sound();break;}
case 'copy-message':await navigator.clipboard.writeText(chat().messages[Number(a.dataset.index)].text);toast('Copied.');break;
case 'delete-note':S.notes=S.notes.filter(x=>x.id!==a.dataset.id);noteId=null;persist();render();break;
case 'export-notes':await flush();if(await api.exportNotes(subjectId))toast('Notes exported.');break;
case 'exam':editExam(a.dataset.id);break;
case 'save-exam':{const date=$('#f-exam-date').value;if(!date)return toast('Choose an exam date.');let exam=S.exams.find(x=>x.id===a.dataset.id);if(!exam){exam={id:id()};S.exams.push(exam)}Object.assign(exam,{subjectId:$('#exam-subject').value,title:$('#f-exam-title').value.trim()||'Exam',date,scope:$('#f-exam-scope').value.trim()});closeModal();persist();render();break;}
case 'delete-exam':S.exams=S.exams.filter(x=>x.id!==a.dataset.id);closeModal();persist();render();break;
case 'generate-practice':{tab='Tutor';render();draft=`Give me one practice question${lesson()?' for lesson '+lesson().number:''}${example?' based on Example '+example:''} using the selected sources. Use provide_practice, keep the answer out of your chat explanation, and use calculate to check numerical results where appropriate.`;$('#prompt').value=draft;$('#prompt').focus();break;}
case 'reveal-practice':{const solution=[...document.querySelectorAll('[data-solution]')].find(x=>x.dataset.solution===a.dataset.key);solution.hidden=!solution.hidden;break;}
case 'rate-practice':{let attempt=S.attempts.find(x=>x.key===a.dataset.key);if(!attempt){attempt={id:id(),key:a.dataset.key,subjectId,answer:'',createdAt:new Date().toISOString()};S.attempts.push(attempt)}attempt.rating=a.dataset.rating;persist();toast(a.dataset.rating==='unsure'?'Saved for mistake review.':'Reflection saved.');break;}
case 'review-mistakes':{const unsure=new Set(S.attempts.filter(x=>x.subjectId===subjectId&&x.rating==='unsure').map(x=>x.key));const items=practiceItems().filter(x=>unsure.has(x.key));modal('Questions to revisit',items.map(x=>`<div class="source-preview">${md(x.question)}</div>`).join('')||'<p>No questions marked unsure yet. Use your reflection after a practice attempt to save them here.</p>');mathRender($('#modal'));break;}
case 'discuss-practice':{const p=practiceItems().find(x=>x.key===a.dataset.key),answer=S.attempts.find(x=>x.key===a.dataset.key)?.answer||'';if(!answer.trim())return toast('Write an attempt first so your tutor can discuss it.');newChat();draft=`Please review my working, identify the step that needs attention, and help me understand it.\nQuestion: ${p.question}\nMy attempt: ${answer}`;render();break;}
case 'whiteboard':modal('Write or sketch your working',`<p>Draw with a mouse or stylus, then add the image to your tutor sources. Typed working and photo uploads are also available.</p><canvas id="working-board" aria-label="Drawing board"></canvas><div class="row" style="margin-top:12px">${btn('Undo','board-undo','secondary')}${btn('Redo','board-redo','secondary')}${btn('Clear','board-clear','secondary')}</div>`,btn('Add drawing to conversation','save-board','primary'));board=Whiteboard.mount($('#working-board'));break;
case 'board-undo':board?.undo();break;
case 'board-redo':board?.redo();break;
case 'board-clear':board?.clear();break;
case 'save-board':{if(!board||board.empty())return toast('Draw your working first.');await flush();const src=await api.saveDrawing({subjectId,image:board.image(),name:'My working · '+new Date().toLocaleTimeString('en-GB',{timeZone:'Asia/Riyadh',hour:'2-digit',minute:'2-digit'})});S.sources.push(src);activeSources.push(src.id);if(chat())chat().sourceIds=[...activeSources];closeModal();persist();render();toast('Drawing attached. Ask the tutor to review your working.');break;}
case 'geometry':{let host=$('#geometry-host');if(!host){tab='Tutor';render();host=$('#geometry-host')}Geometry.mount(host,'triangle',snapshot=>{if(chat()){chat().geometry=snapshot;persist()}},chat()?.geometry);host.scrollIntoView({block:'nearest'});icons();break;}
case 'connect-key':modal('Connect your OpenAI API account',`<p>Use the API key from your separate account. It is encrypted locally and never included in backups.</p><div class="field"><label for="api-key">API key</label><input id="api-key" type="password" autocomplete="off" spellcheck="false" placeholder="Paste your API key here"></div>`,btn('Save connection','save-key','primary'));break;
case 'save-key':{const secret=$('#api-key').value;const status=await api.setKey(secret);$('#api-key').value='';connected=true;connectionPersistent=status.persistent;closeModal();render();toast(status.persistent?'Key saved securely. Choose a model available to your account.':'Connected for this session. Secure storage is unavailable, so the key was not written to disk.');break;}
case 'disconnect-key':await api.setKey(null);connected=false;render();toast('API connection removed.');break;
case 'load-models':a.disabled=true;try{const models=await api.models();$('#models-list').innerHTML=models.map(m=>`<option value="${esc(m)}"></option>`).join('');toast(`${models.length} models loaded. Choose one in the Model ID field.`);$('#model-name').focus()}finally{a.disabled=false}break;
case 'move-tab':{const i=S.settings.tabs.indexOf(a.dataset.tab);if(i>0)[S.settings.tabs[i-1],S.settings.tabs[i]]=[S.settings.tabs[i],S.settings.tabs[i-1]];persist();render();break;}
case 'backup':await flush();if(await api.backup())toast('Backup exported without API credentials.');break;
case 'restore':modal('Restore a workspace',`<p>Restoring replaces your current chats, notes, and settings. Export a backup first if you want to keep them. Original source files may need to be imported again on another computer.</p>`,btn('Choose backup and restore','confirm-restore','primary'));break;
case 'confirm-restore':{const restored=await api.restore();if(restored){S=restored;subjectId=null;chatId=null;lessonId=null;view='home';closeModal();render();toast('Workspace restored.')}break;}
case 'open-data':await api.openData();break;
case 'close-modal':closeModal();break;
}}catch(err){toast(err.message)}icons();});
document.addEventListener('click',e=>{const w=e.target.closest('[data-window]');if(w)api.window(w.dataset.window);const link=e.target.closest('.message-text a');if(link){e.preventDefault();toast('Copy the link to open it in your browser.')}});
document.addEventListener('keydown',e=>{if((e.ctrlKey||e.metaKey)&&e.key.toLowerCase()==='k'){e.preventDefault();if(!$('#modal').open)searchDialog()}});
const handle=$('#resize-handle');handle.onpointerdown=e=>{handle.setPointerCapture(e.pointerId);const start=e.clientX,width=S.settings.sidebarWidth;const move=event=>{S.settings.sidebarWidth=Math.max(190,Math.min(360,width+event.clientX-start));applyTheme()};const end=()=>{handle.removeEventListener('pointermove',move);handle.removeEventListener('pointerup',end);persist()};handle.addEventListener('pointermove',move);handle.addEventListener('pointerup',end)};handle.onkeydown=e=>{if(['ArrowLeft','ArrowRight'].includes(e.key)){S.settings.sidebarWidth=Math.max(190,Math.min(360,S.settings.sidebarWidth+(e.key==='ArrowLeft'?-8:8)));applyTheme();persist()}};
$('#modal').addEventListener('click',e=>{if(e.target===$('#modal'))closeModal()});
api.onProgress(info=>{if(info.type==='import')toast(info.text);else if($('#thinking-label'))$('#thinking-label').textContent=info.text});
async function init(){S=await api.load();updateState=await api.updateStatus();const connection=await api.keyStatus();connected=connection.connected;connectionPersistent=connection.persistent;subjectId=S.ui.subject;chatId=S.ui.chat;lessonId=S.ui.lesson;tab=S.ui.tab||'Tutor';view=S.ui.view||'home';if(subjectId&&!subject())view='home';if(view==='subject')activeSources=chat()?.sourceIds||lesson()?.sourceIds||subjectsSources().map(x=>x.id);draft=chat()?.draft||'';render()}
init().catch(e=>{$('#main').innerHTML='<div class="content"><h1>Could not open your workspace</h1><p>'+esc(e.message)+'</p></div>'});
})();
